```javascript
const { Client, Intents } = require('discord.js');

const client = new Client({ intents: [Intents.FLAGS.GUILDS, Intents.FLAGS.GUILD_MEMBERS] });

client.on('ready', () => console.log(`Logged in as ${client.user.tag}!`));

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === 'ban') {
    const member = interaction.options.getMember('member');
    const reason = interaction.options.getString('reason');

    if (!member) {
      await interaction.reply({ content: 'Please provide a valid member.', ephemeral: true });
      return;
    }

    await member.ban({ reason });
    await interaction.reply({ content: `Banned ${member.user.tag} for ${reason}`, ephemeral: true });
  }
});

client.login('YOUR_BOT_TOKEN');
```

**Explanation:**

1. **Imports:** Imports necessary modules from `discord.js`.
2. **Client:** Creates a new Discord client with required intents.
3. **Ready Event:** Logs a message when the bot is ready.
4. **Interaction Create Event:**
   - Checks if the interaction is a command.
   - If the command is `ban`:
     - Retrieves the member and reason from interaction options.
     - Bans the member with the provided reason.
     - Sends a confirmation message to the user.
5. **Login:** Logs in the bot with your bot token

